1	package custody
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 销毁时间边界回归的公共前置：
10	//
11	//	原样 P 初始 10.000，由张三在实验室A交给李四并在实验室B确认接收，
12	//	随后李四分出 4.000 子样 C，原样剩余 6.000。
13	//
14	// 关键在于历史的“追加次序”和“时间先后”不一致：
15	//
16	//	历史追加次序：register -> transfer-out -> transfer-in -> split
17	//	实际时间先后：register -> transfer-out -> split(sAt) -> transfer-in(rAt)
18	//
19	// 分装记录虽最后追加，时间却早于此前的接收记录（分装没有外部时间，
20	// 沿用创建时刻，保持既有时间处理行为）。因此最晚历史时刻是接收时间
21	// rAt，而不是历史末尾的分装时间 sAt。
22	//
23	// 返回登记、交出、接收、分装四个实际时刻。
24	func setupReceivedThenSplit(t *testing.T) (s *Store, regAt, hAt, rAt, sAt time.Time) {
25		t.Helper()
26		s, _ = fixedStore(t)
27	
28		regAt = time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
29		hAt = time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
30		rAt = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
31		sAt = time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC) // 晚于交出、早于接收
32	
33		s.now = func() time.Time { return regAt }
34		mustRegister(t, s, "P", "10.000", "张三", "实验室A")
35	
36		if _, err := s.Handover(HandoverInput{
37			TransferID: "TR-1", SampleID: "P",
38			FromHolder: "张三", FromLocation: "实验室A",
39			ToHolder: "李四", ToLocation: "实验室B",
40			HandedOverAt: hAt,
41		}); err != nil {
42			t.Fatalf("发起交接: %v", err)
43		}
44		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室B", rAt}); err != nil {
45			t.Fatalf("确认接收: %v", err)
46		}
47	
48		// 分装在接收之后才追加，时钟却拨到接收之前：历史末尾不是最晚时刻。
49		s.now = func() time.Time { return sAt }
50		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
51			{ID: "C", Qty: "4.000"},
52		}}); err != nil {
53			t.Fatalf("分装: %v", err)
54		}
55	
56		p, err := s.GetSample("P")
57		if err != nil {
58			t.Fatal(err)
59		}
60		// 前置条件自检：确保场景确实是“末尾更早、接收最晚”，避免测试空转。
61		if len(p.History) != 4 {
62			t.Fatalf("前置条件：原样应有 4 条历史, got %+v", p.History)
63		}
64		wantKinds := []string{"register", "transfer-out", "transfer-in", "split"}
65		for i, k := range wantKinds {
66			if p.History[i].Kind != k {
67				t.Fatalf("前置条件：历史追加次序错误: %+v", p.History)
68			}
69		}
70		if !p.History[len(p.History)-1].Time.Equal(sAt) {
71			t.Fatalf("前置条件：历史末尾应为分装时刻 %s, got %s",
72				sAt, p.History[len(p.History)-1].Time)
73		}
74		if !sAt.Before(rAt) {
75			t.Fatalf("前置条件：分装时间应早于接收时间")
76		}
77		if p.Remaining != "6.000" || p.Holder != "李四" || p.Location != "实验室B" {
78			t.Fatalf("前置条件：原样应由李四在实验室B持有剩余 6.000: %+v", p)
79		}
80		if p.PendingTransfer != nil {
81			t.Fatalf("前置条件：接收完成后不应有待确认交接")
82		}
83		return s, regAt, hAt, rAt, sAt
84	}
85	
86	// sameHistory 逐条比较保管历史的内容与次序（含时间实际时刻与详情文本）。
87	func sameHistory(a, b []History) bool {
88		if len(a) != len(b) {
89			return false
90		}
91		for i := range a {
92			if a[i].Kind != b[i].Kind || !a[i].Time.Equal(b[i].Time) ||
93				a[i].Holder != b[i].Holder || a[i].Location != b[i].Location ||
94				a[i].Detail != b[i].Detail {
95				return false
96			}
97		}
98		return true
99	}
100	
101	// TestDestroyTimeBoundChecksAllHistoryNotLastEntry 销毁时间晚于历史末尾的
102	// 分装时间、却早于更早追加的接收时间时，必须返回 ErrInvalid；不能因为
103	// 比较对象只是最后一条历史就接受。
104	func TestDestroyTimeBoundChecksAllHistoryNotLastEntry(t *testing.T) {
105		s, _, _, rAt, sAt := setupReceivedThenSplit(t)
106	
107		before, err := s.GetSample("P")
108		if err != nil {
109			t.Fatal(err)
110		}
111		childBefore, err := s.GetSample("C")
112		if err != nil {
113			t.Fatal(err)
114		}
115	
116		// dMid 晚于末尾的分装（10:00），早于接收（12:00）。
117		dMid := time.Date(2026, 10, 2, 11, 0, 0, 0, time.UTC)
118		in := DestroyInput{
119			SampleID: "P", Operator: "李四", Location: "实验室B",
120			At: dMid, Reason: "实验结束按规程销毁",
121		}
122		if _, err := s.Destroy(in); !errors.Is(err, ErrInvalid) {
123			t.Fatalf("晚于分装但早于接收的销毁时间应返回 ErrInvalid, got %v", err)
124		}
125	
126		// 同一实际时刻换 UTC+8 表示（当地钟点 19:00）仍须拒绝：
127		// 判断只看实际时刻，不能按显示钟点或时区名称决定先后。
128		tokyo := time.FixedZone("UTC+8", 8*60*60)
129		inZone := in
130		inZone.At = dMid.In(tokyo)
131		if _, err := s.Destroy(inZone); !errors.Is(err, ErrInvalid) {
132			t.Fatalf("换时区表示同一过早时刻仍应返回 ErrInvalid, got %v", err)
133		}
134	
135		// 再早于最晚历史 1 秒也拒绝（边界的严格一侧）。
136		tooEarly := in
137		tooEarly.At = rAt.Add(-time.Second)
138		if _, err := s.Destroy(tooEarly); !errors.Is(err, ErrInvalid) {
139			t.Fatalf("早于最晚历史 1 秒应返回 ErrInvalid, got %v", err)
140		}
141	
142		// 拒绝后原样状态完整保留。
143		after, err := s.GetSample("P")
144		if err != nil {
145			t.Fatal(err)
146		}
147		if after.Remaining != "6.000" || after.InitialQty != "10.000" {
148			t.Fatalf("拒绝后数量应不变: init=%s rem=%s", after.InitialQty, after.Remaining)
149		}
150		if after.Holder != "李四" || after.Location != "实验室B" {
151			t.Fatalf("拒绝后持有人/地点应不变: %+v", after)
152		}
153		if after.ParentID != "" || len(after.Children) != 1 || after.Children[0] != "C" {
154			t.Fatalf("拒绝后来源关系与子样列表应不变: parent=%q children=%v",
155				after.ParentID, after.Children)
156		}
157		if after.PendingTransfer != nil {
158			t.Fatalf("拒绝不应产生待确认交接: %+v", after.PendingTransfer)
159		}
160		if after.Destruction != nil {
161			t.Fatalf("拒绝后不应出现销毁信息: %+v", after.Destruction)
162		}
163		if !sameHistory(after.History, before.History) {
164			t.Fatalf("拒绝后已有历史内容与次序应保持原样:\nbefore=%+v\nafter=%+v",
165				before.History, after.History)
166		}
167		// 历史末尾没有被追加销毁事件，仍是时间更早的分装事件。
168		if last := after.History[len(after.History)-1]; last.Kind == "destroy" ||
169			!last.Time.Equal(sAt) {
170			t.Fatalf("历史末尾应仍是原分装事件: %+v", last)
171		}
172	
173		// 子样同样不受失败销毁影响。
174		childAfter, err := s.GetSample("C")
175		if err != nil {
176			t.Fatal(err)
177		}
178		if childAfter.ParentID != "P" || childAfter.Remaining != "4.000" ||
179			childAfter.InitialQty != "4.000" || childAfter.Holder != "李四" ||
180			childAfter.Location != "实验室B" || childAfter.Destruction != nil {
181			t.Fatalf("拒绝销毁原样不应改动子样: %+v", childAfter)
182		}
183		if !sameHistory(childAfter.History, childBefore.History) {
184			t.Fatalf("子样历史不应变化: before=%+v after=%+v",
185				childBefore.History, childAfter.History)
186		}
187	}
188	
189	// TestDestroyAtLatestHistoryInstantSucceedsAcrossZones 销毁时间恰好等于
190	// 自身最晚历史时刻（接收时刻）时允许销毁，即使该时刻用另一时区表示；
191	// 此前被拒绝的请求不影响后续合法销毁。
192	func TestDestroyAtLatestHistoryInstantSucceedsAcrossZones(t *testing.T) {
193		s, regAt, hAt, rAt, sAt := setupReceivedThenSplit(t)
194		tokyo := time.FixedZone("UTC+8", 8*60*60)
195	
196		// 先制造一次过早请求并被拒绝，确认失败不留下任何痕迹。
197		tooEarly := DestroyInput{
198			SampleID: "P", Operator: "李四", Location: "实验室B",
199			At: rAt.Add(-time.Minute), Reason: "实验结束按规程销毁",
200		}
201		if _, err := s.Destroy(tooEarly); !errors.Is(err, ErrInvalid) {
202			t.Fatalf("前置：过早销毁应 ErrInvalid, got %v", err)
203		}
204	
205		// 恰好等于最晚历史时刻，用 UTC+8 表示（当地 20:00 == UTC 12:00）。
206		atBoundary := tooEarly
207		atBoundary.At = rAt.In(tokyo)
208		destroyed, err := s.Destroy(atBoundary)
209		if err != nil {
210			t.Fatalf("销毁时间等于最晚历史时刻应允许（跨时区表示）: %v", err)
211		}
212		if destroyed.Remaining != "0.000" {
213			t.Fatalf("销毁后剩余量应为 0.000, got %s", destroyed.Remaining)
214		}
215		if destroyed.InitialQty != "10.000" {
216			t.Fatalf("初始量应保留, got %s", destroyed.InitialQty)
217		}
218		d := destroyed.Destruction
219		if d == nil {
220			t.Fatalf("成功销毁应返回销毁信息")
221		}
222		if d.Operator != "李四" || d.Location != "实验室B" ||
223			d.Reason != "实验结束按规程销毁" || d.Qty != "6.000" || !d.At.Equal(rAt) {
224			t.Fatalf("销毁信息（操作人/地点/原因/时间/实际销毁量）错误: %+v", d)
225		}
226		if d.At.Location() != time.UTC {
227			// 内部统一按实际时刻保存，不依赖入参时区。
228			t.Fatalf("销毁时间应按实际时刻规范化保存, got location %s", d.At.Location())
229		}
230	
231		// 原有历史保留，销毁事件追加在末尾；时间按实际时刻相等。
232		wantKinds := []string{"register", "transfer-out", "transfer-in", "split", "destroy"}
233		if len(destroyed.History) != len(wantKinds) {
234			t.Fatalf("历史条数错误: %+v", destroyed.History)
235		}
236		for i, k := range wantKinds {
237			if destroyed.History[i].Kind != k {
238				t.Fatalf("历史内容或次序错误: %+v", destroyed.History)
239			}
240		}
241		wantTimes := []time.Time{regAt, hAt, rAt, sAt, rAt}
242		for i, want := range wantTimes {
243			if !destroyed.History[i].Time.Equal(want) {
244				t.Fatalf("第 %d 条历史时间错误: got %s want %s",
245					i, destroyed.History[i].Time, want)
246			}
247		}
248		last := destroyed.History[len(destroyed.History)-1]
249		if last.Holder != "李四" || last.Location != "实验室B" {
250			t.Fatalf("销毁事件的持有人/地点错误: %+v", last)
251		}
252		if destroyed.Holder != "李四" || destroyed.Location != "实验室B" {
253			t.Fatalf("销毁后持有人/地点应保留为销毁前记录: %+v", destroyed)
254		}
255	
256		// 再次查询结果一致：仍为 0.000 且销毁信息完整。
257		again, err := s.GetSample("P")
258		if err != nil {
259			t.Fatal(err)
260		}
261		if again.Remaining != "0.000" || again.Destruction == nil ||
262			again.Destruction.Qty != "6.000" || !again.Destruction.At.Equal(rAt) {
263			t.Fatalf("重新查询销毁结果错误: %+v", again)
264		}
265		if !sameHistory(again.History, destroyed.History) {
266			t.Fatalf("重新查询历史应与销毁返回一致")
267		}
268	}
269	
270	// TestDestroyTimeBoundIgnoresChildHistory 销毁时间只看被销毁样品自身的
271	// 历史：已分出的子样另有更晚的交出/接收记录，不推迟原样的可销毁时间，
272	// 实际销毁量也只含原样剩余量，子样一切不变。
273	func TestDestroyTimeBoundIgnoresChildHistory(t *testing.T) {
274		s, _, _, rAt, sAt := setupReceivedThenSplit(t)
275	
276		// 子样 C 此后独立交接并完成接收，时间远晚于原样自身的最晚历史。
277		cHandAt := rAt.Add(2 * time.Hour) // 14:00
278		cRecvAt := rAt.Add(3 * time.Hour) // 15:00
279		if _, err := s.Handover(HandoverInput{
280			TransferID: "TC", SampleID: "C",
281			FromHolder: "李四", FromLocation: "实验室B",
282			ToHolder: "王五", ToLocation: "实验室C",
283			HandedOverAt: cHandAt,
284		}); err != nil {
285			t.Fatalf("子样交出: %v", err)
286		}
287		if _, err := s.Confirm(ConfirmInput{"TC", "王五", "实验室C", cRecvAt}); err != nil {
288			t.Fatalf("子样接收: %v", err)
289		}
290	
291		// 原样销毁时间满足自身边界（晚于 rAt），但严格早于子样的更晚记录。
292		destroyPAt := rAt.Add(30 * time.Minute) // 12:30，早于子样交出 14:00
293		p, err := s.Destroy(DestroyInput{
294			SampleID: "P", Operator: "李四", Location: "实验室B",
295			At: destroyPAt, Reason: "实验结束按规程销毁",
296		})
297		if err != nil {
298			t.Fatalf("原样满足自身时间条件即可销毁，不受子样更晚历史影响: %v", err)
299		}
300		if p.Remaining != "0.000" || p.Destruction == nil || p.Destruction.Qty != "6.000" {
301			t.Fatalf("原样实际销毁量应只含自身剩余量 6.000: %+v", p)
302		}
303		if !p.Destruction.At.Equal(destroyPAt) {
304			t.Fatalf("原样销毁时间错误: got %s want %s", p.Destruction.At, destroyPAt)
305		}
306		if len(p.Children) != 1 || p.Children[0] != "C" || p.ParentID != "" {
307			t.Fatalf("销毁原样应保留父子关系: parent=%q children=%v", p.ParentID, p.Children)
308		}
309		// 原样历史只追加自身销毁事件，不混入子样事件。
310		wantKinds := []string{"register", "transfer-out", "transfer-in", "split", "destroy"}
311		if len(p.History) != len(wantKinds) {
312			t.Fatalf("原样历史条数错误: %+v", p.History)
313		}
314		for i, k := range wantKinds {
315			if p.History[i].Kind != k {
316				t.Fatalf("原样历史内容/次序错误: %+v", p.History)
317			}
318		}
319	
320		// 子样数量、持有人、地点、接收状态与自身保管历史全部不变。
321		c, err := s.GetSample("C")
322		if err != nil {
323			t.Fatal(err)
324		}
325		if c.ParentID != "P" || c.InitialQty != "4.000" || c.Remaining != "4.000" {
326			t.Fatalf("子样数量与来源关系应不变: %+v", c)
327		}
328		if c.Holder != "王五" || c.Location != "实验室C" {
329			t.Fatalf("子样持有人/地点应不变: %+v", c)
330		}
331		if c.Destruction != nil || c.PendingTransfer != nil {
332			t.Fatalf("子样不应出现销毁信息或待确认交接: destruction=%+v pending=%+v",
333				c.Destruction, c.PendingTransfer)
334		}
335		cWantKinds := []string{"split", "transfer-out", "transfer-in"}
336		cWantTimes := []time.Time{sAt, cHandAt, cRecvAt}
337		if len(c.History) != len(cWantKinds) {
338			t.Fatalf("子样历史条数应不变: %+v", c.History)
339		}
340		for i, k := range cWantKinds {
341			if c.History[i].Kind != k || !c.History[i].Time.Equal(cWantTimes[i]) {
342				t.Fatalf("子样历史内容/次序/时间应不变: %+v", c.History)
343			}
344		}
345		tr, err := s.GetTransfer("TC")
346		if err != nil {
347			t.Fatal(err)
348		}
349		if !tr.Confirmed || tr.ConfirmedBy != "王五" || tr.Qty != "4.000" ||
350			tr.ReceivedAt == nil || !tr.ReceivedAt.Equal(cRecvAt) {
351			t.Fatalf("子样交接的已确认状态应不变: %+v", tr)
352		}
353	}
