// validateDestroyedTime 核对一份带销毁信息的样品记录其销毁时间是否成立：
//   - 销毁时间必须存在且非零值（旧数据缺失或显式零值都拒绝，与是否有保管
//     历史无关）；
//   - 销毁时间按实际时刻不得早于该样品自身任何一条保管历史的发生时刻
//     （恰好等于最晚历史时刻合法；同一时刻的不同时区表示结果相同）。
//
// 只看该编号样品自己的历史：已分出的子样或同一份数据中其他样品更晚的
// 交接记录都不影响本样品可销毁的时间。保管历史按操作发生顺序保存、不保证
// 时间递增，因此逐条核对全部历史而不是只看末尾；核对只读取历史，绝不
// 重排或改写记录。任一不符都返回包装了 ErrInvalid 的错误，信息写明样品
// 编号；时间倒置时同时给出销毁时间与冲突历史的时间。
func validateDestroyedTime(sampleID string, rec *sampleRecord) error {
	at := rec.Destroyed.At
	if at.IsZero() {
		return fmt.Errorf("%w: 样品 %q 的销毁时间缺失或为零值，无法恢复", ErrInvalid, sampleID)
	}
	for _, h := range rec.History {
		if at.Before(h.Time) {
			return fmt.Errorf("%w: 样品 %q 的销毁时间 %s 早于已有保管历史（%s）的时间 %s，无法恢复",
				ErrInvalid, sampleID, at.Format(time.RFC3339), h.Kind, h.Time.Format(time.RFC3339))
		}
	}
	return nil
}
```

